argv:
set -euo pipefail
pick() {
  for d in "${LLVM_BIN:-}" /opt/homebrew/opt/llvm/bin /usr/local/opt/llvm/bin; do
    if [ -n "$d" ] && [ -x "$d/clang" ] && [ -x "$d/llvm-ar" ]; then echo "$d"; return 0; fi
  done
  for v in 21 20 19 18 17; do
    if [ -x "/usr/lib/llvm-$v/bin/clang" ] && [ -x "/usr/lib/llvm-$v/bin/llvm-ar" ]; then echo "/usr/lib/llvm-$v/bin"; return 0; fi
  done
  return 1
}
llvm=$(pick) || { echo 'no LLVM clang with llvm-ar found; set LLVM_BIN'; exit 2; }
command -v wasm-bindgen-test-runner >/dev/null || { echo 'wasm-bindgen-test-runner is not on PATH'; exit 2; }
command -v node >/dev/null || { echo 'node is not on PATH'; exit 2; }
export CC_wasm32_unknown_unknown="$llvm/clang" AR_wasm32_unknown_unknown="$llvm/llvm-ar" CARGO_TARGET_WASM32_UNKNOWN_UNKNOWN_RUNNER=wasm-bindgen-test-runner
cargo test -p dxn_dtcg --features expressions --target wasm32-unknown-unknown --test expressions_wasm
